def get_placement_coords(placement):
    if not placement:
        return [0.0, 0.0, 0.0]
    local_origin = [0.0, 0.0, 0.0]
    rel = placement.RelativePlacement
    if rel and rel.Location:
        local_origin = list(rel.Location.Coordinates)
    if len(local_origin) == 2:
        local_origin.append(0.0)
    if placement.PlacementRelTo:
        parent_origin = get_placement_coords(placement.PlacementRelTo)
        return [local_origin[i] + parent_origin[i] for i in range(3)]
    return local_origin

for s in model.by_type('IfcSpace')[:5]:
